import 'dart:convert';import 'package:flutter/material.dart';import '../../../core/data/astro_repository.dart';import '../../../shared/widgets/app_components.dart';
class JournalScreen extends StatefulWidget{const JournalScreen({super.key,this.prompt='What would you like to reflect on today?',this.entry});final String prompt;final Map<String,Object?>? entry;@override State<JournalScreen> createState()=>_JournalScreenState();}
class _JournalScreenState extends State<JournalScreen>{late final TextEditingController body,tags;String? mood;
@override void initState(){super.initState();final e=widget.entry;body=TextEditingController(text:e==null?'':e['body'] as String);tags=TextEditingController(text:e==null?'':(jsonDecode(e['tags'] as String) as List).join(', '));mood=e==null?null:e['mood'] as String?;}
@override void dispose(){body.dispose();tags.dispose();super.dispose();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.entry==null?'Private journal':'Edit reflection')),body:ListView(padding:const EdgeInsets.all(20),children:[const InfoCard('Your journal stays on this device. It is never included in reading shares.'),const SizedBox(height:16),Text(widget.prompt,style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:10),TextField(controller:body,minLines:8,maxLines:16,maxLength:12000,decoration:const InputDecoration(hintText:'Write something for yourself…',alignLabelWithHint:true)),const SizedBox(height:12),TextField(controller:tags,decoration:const InputDecoration(labelText:'Tags (comma separated)')),const SizedBox(height:12),DropdownButtonFormField<String>(initialValue:mood,decoration:const InputDecoration(labelText:'Optional mood'),items:['Calm','Curious','Hopeful','Thoughtful','Other'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>mood=v)),const SizedBox(height:18),FilledButton(onPressed:body.text.trim().isEmpty?null:()async{await AstroRepository.instance.saveJournal(id:widget.entry==null?null:widget.entry!['id'] as String,body:body.text.trim(),prompt:widget.prompt,tags:tags.text.split(',').map((v)=>v.trim()).where((v)=>v.isNotEmpty).toList(),mood:mood);if(mounted)Navigator.pop(context,true);},child:const Text('Save privately'))]));}
